def _set_current_value(models_by_name, component, definition, value, now):
    SignalBinding = models_by_name['SignalBinding']
    CurrentSignalValue = models_by_name['CurrentSignalValue']
    binding, _ = SignalBinding.objects.get_or_create(
        component=component,
        signal_definition=definition,
        defaults={
            'source_protocol': 'rest',
            'source_metric': definition.code,
        },
    )
    CurrentSignalValue.objects.update_or_create(
        binding=binding,
        defaults={
            'value': value,
            'source_timestamp': now,
            'quality': 'good',
        },
    )


