def restore_legacy_data(apps, schema_editor):
    Che = apps.get_model('minitos_core', 'Che')
    CheComponent = apps.get_model('minitos_core', 'CheComponent')
    CurrentSignalValue = apps.get_model('minitos_core', 'CurrentSignalValue')
    EquipmentPart = apps.get_model('minitos_core', 'EquipmentPart')
    EquipmentType = apps.get_model('minitos_core', 'EquipmentType')
    EquipmentTypeComponent = apps.get_model('minitos_core', 'EquipmentTypeComponent')

    for equipment_type in EquipmentType.objects.all():
        profiles = {profile.role: profile for profile in EquipmentTypeComponent.objects.filter(equipment_type=equipment_type)}
        drive = profiles.get('drive')
        hoist = profiles.get('hoist')
        engine = profiles.get('engine')
        power = engine or profiles.get('electric_power_source')
        store = profiles.get('battery') if equipment_type.energy_source == 'Electric' else profiles.get('fuel_tank')
        updates = {
            'driving_speed_empty_kmh': (drive.default_configuration.get('maximum_speed_empty_m_s', 0) * 3.6) if drive else 0,
            'driving_speed_full_load_kmh': (drive.default_configuration.get('maximum_speed_loaded_m_s', 0) * 3.6) if drive else 0,
            'lifting_speed_empty_m_per_min': (hoist.default_configuration.get('maximum_speed_empty_m_s', 0) * 60) if hoist else 0,
            'lifting_speed_full_load_m_per_min': (hoist.default_configuration.get('maximum_speed_loaded_m_s', 0) * 60) if hoist else 0,
            'turning_radius_m': drive.default_configuration.get('turning_radius_m', 0) if drive else 0,
            'engine_type': engine.default_configuration.get('engine_type') if engine else None,
            'power_rating_kw': power.default_configuration.get('rated_power_kw', 0) if power else 0,
            'fuel_tank_capacity': (
                store.default_configuration.get('capacity_kwh', 0)
                if store and store.role == 'battery'
                else (store.default_configuration.get('capacity_l', 0) if store else 0)
            ),
        }
        EquipmentType.objects.filter(pk=equipment_type.pk).update(**updates)
        for profile in profiles.values():
            if profile.default_configuration.get('_migrated_from_equipment_part'):
                EquipmentPart.objects.update_or_create(
                    name=profile.display_name,
                    defaults={
                        'equipment_type_id': equipment_type.pk,
                        'running_hours': profile.default_configuration.get('legacy_running_hours', 0),
                    },
                )

    for che in Che.objects.all():
        values = {
            row.binding.signal_definition.code: row.value
            for row in CurrentSignalValue.objects.filter(binding__component__che_id=che.pk).select_related(
                'binding__signal_definition'
            )
        }
        engine = CheComponent.objects.filter(che_id=che.pk, role='engine').first()
        running_hours_since_maintenance = (
            float(engine.engine.hours_since_maintenance)
            if engine and hasattr(engine, 'engine') else 0
        )
        Che.objects.filter(pk=che.pk).update(
            fuel_level=values.get('energystoragesystem.energy.level', 100),
            twistlock_closed=values.get('spreader.locked.status', False),
            running_hours=values.get('che.on.total_hours', 0),
            running_hours_since_last_maintenance=running_hours_since_maintenance,
        )


